.nv-verde { color: %(g)s; }
/* La barra de estado, abajo a lo ancho: a dónde apunta web.local */
.nv-estado { background-color: alpha(@theme_fg_color, 0.035); border-top: 1px solid alpha(@theme_fg_color, 0.08);
             padding: 5px 16px; }
